      ref={controlsRef}
      makeDefault
      enableDamping
      dampingFactor={0.05}
      minDistance={1.8}
      maxDistance={12}
      maxPolarAngle={Math.PI / 2 + 0.05} // Don't go below floor
      autoRotate={cameraView === 'tour'}
      autoRotateSpeed={1.2}
    />
  );
}

